-- =====================================================================================
-- LEMON CAPS - CATALOGO PUBLICO
-- 20260922000000_reformulacao_conforme_normas.sql
--
-- Grava a FORMULACAO PROPOSTA pela reformulacao regulatoria de 16/09/2026 nos 24 produtos ativos do
-- catalogo, casando por SLUG (nunca por UUID).
--
-- CONTEXTO
-- Ordem do dono, 15/09/2026: "altere os insumos para os permitidos, refaca as formulacoes para todas
-- estarem dentro das normas, pesquise os laudos antes". Em 16/09/2026 tres frentes reformularam os 24
-- produtos (memorial por produto em docs/conformidade/reformulacao/<slug>.md) e a fase 3 verificou,
-- harmonizou e consolidou (docs/conformidade/REFORMULACAO-CONSOLIDADA-2026-09-16.md; tabelas em
-- docs/conformidade/TABELAS-NUTRICIONAIS-2026-09-16.md).
--
-- FONTES (todas em disco, lidas em 16/09/2026)
--   docs/conformidade/IN28-2018-ANEXO-I-LITERAL.md            constituintes e formas autorizadas (nome exato)
--   docs/conformidade/IN28-2018-ANEXO-III-LITERAL.md          minimos por grupo populacional
--   docs/conformidade/IN28-2018-ANEXOS-IV-V-VI-LITERAL.md     maximos, alegacoes e advertencias obrigatorias
--   docs/conformidade/LAUDOS-INVENTARIO-2026-09-16.md         laudos de insumo (lote, validade, teor)
--   docs/conformidade/MEMORIAIS-INVENTARIO-2026-09-16.md      o que a fabrica pesa hoje
--   docs/conformidade/PADRAO-ANVISA-TABELA-NUTRICIONAL-2026-09-16.md  gabarito RDC 429/2020 + IN 75/2020
--   docs/conformidade/reformulacao/<slug>.md                  memorial de reformulacao de cada produto
--
-- *****************************************************************************************
-- ADVERTENCIA: ESTA MIGRATION DESCREVE A FORMULACAO PROPOSTA. SO DEVE SER APLICADA QUANDO A
-- FABRICA CONFIRMAR QUE PASSA A PRODUZIR ASSIM (MEMORIAL REVISADO + LAUDOS + ARTE NOVA),
-- PORQUE O CATALOGO B2B DESCREVE O PRODUTO QUE SE VENDE.
-- Ela substitui as composicoes ativas atuais (sejam as do cadastro-teto ou as da
-- 20260920000000_composicoes_conforme_rotulo.sql, se esta tiver sido aplicada) e deixa os selos de
-- conformidade (20260921000000 / 20260921100000) sem lastro: o bloco final zera
-- compliance_verified_at das 24 formulas. O selo volta por migration propria, com auditoria
-- contra a formula efetivamente produzida.
-- *****************************************************************************************
--
-- OS 24 PRODUTOS E O VEREDITO ESPERADO DEPOIS DA REFORMULACAO (linhas de composicao gravadas):
--   multivitaminico                              19 linha(s)  CONFORME CONDICIONADO
--   zma-zinco-magnesio-e-vitamina-d               7 linha(s)  CONFORME CONDICIONADO
--   biotina-em-capsula                           21 linha(s)  CONFORME CONDICIONADO
--   dores-musculares                             13 linha(s)  CONFORME CONDICIONADO
--   focus-colina                                 10 linha(s)  CONFORME CONDICIONADO
--   multi-vitta-gestante-e-lactante-em-capsula   12 linha(s)  CONFORME CONDICIONADO
--   melatonina-triptofanos-encapsulados           8 linha(s)  CONFORME CONDICIONADO
--   serena                                        9 linha(s)  CONFORME CONDICIONADO
--   detox-matinal-lemon-shot-300g                10 linha(s)  CONFORME CONDICIONADO
--   saude-intestinal                              8 linha(s)  CONFORME CONDICIONADO
--   moro-slim                                     6 linha(s)  CONFORME CONDICIONADO
--   pro-energy                                    9 linha(s)  CONFORME CONDICIONADO
--   emagrecedor-em-capsula                        6 linha(s)  CONFORME CONDICIONADO
--   slim-up-emagrecimento-em-gota                12 linha(s)  CONFORME CONDICIONADO
--   shot-colageno-300-gramas                      9 linha(s)  CONFORME CONDICIONADO
--   omega-pro-tg                                  0 linha(s)  NÃO RESOLVIDO
--   bella-gummy-biotina-em-gummy                  5 linha(s)  CONFORME CONDICIONADO
--   creatina-monohidratada-150g-soluvel           1 linha(s)  CONFORME (condicionado a validação)
--   creatina-monohidratada-300g-soluvel           1 linha(s)  CONFORME (condicionado a validação)
--   creatina-gummy-sabor-frutas-vermelhas         1 linha(s)  CONFORME NOS LIMITES · NÃO RESOLVIDO NA PORÇÃO
--   creatina-em-gummy-sabor-tutti-frutti          1 linha(s)  CONFORME NOS LIMITES · NÃO RESOLVIDO NA PORÇÃO
--   melatonina-em-gummy-sabor-uva                 2 linha(s)  CONFORME CONDICIONADO
--   pre-treino-300-g                             13 linha(s)  CONFORME (condicionado a validação)
--   pre-treino-creatina-sabor-limao-420g         18 linha(s)  CONFORME (condicionado a validação)
--   (omega-pro-tg: NAO RESOLVIDO - sem laudo do oleo, memorial nem rotulo; a composicao atual NAO e tocada;
--    so entram as advertencias do art. 14 da RDC 243/2018, o alergenico peixe, a porcao e a tabela PROVISORIA em metadata.)
--
-- CONVENCOES DAS LINHAS DE COMPOSICAO (harmonizadas entre as tres frentes na fase 3):
--   quantity  = massa do INSUMO pesado por porcao (sal/forma comercial), como o dono decidiu em
--               20260915140000 ("a quantidade exibida continua sendo a massa do sal"); massas < 0,01 mg vao em mcg.
--   ingredient_name = forma do Anexo I + equivalencia em ativo ("Bisglicinato de zinco (equivalente a 15 mg de zinco)").
--   metadata  = procedencia completa: fonte, constituinte, forma_anexo_i, massa_insumo_mg, teor_laudo_pct,
--               fator_conversao (sal->base ou potencia), teor_efetivo_pct, ativo, minimo, maximo, pct_do_maximo,
--               linha_anexo, laudo_lote, laudo_validade, laudo_vencido, status, e_sal, elemento_equivalente.
--   excipientes com massa definida no memorial entram como linhas (papel veiculo/aditivo); capsula nao entra
--   (fora da porcao); nas 4 gomas a base (matriz) nao entra porque as massas individuais estao PENDENTES ou nao
--   cabem na porcao declarada - ficam so na lista de ingredientes.
--   nutritional_info e TEXT no banco (conferido ao vivo em 16/09/2026): recebe a tabela em texto no formato
--   do gabarito; a tabela estruturada vai em formulas.metadata->'reformulacao_2026_09_16'->'tabela_nutricional'.
--
-- O QUE FAZ, NESTA ORDEM:
--   0. Guarda: aborta se nao encontrar exatamente 24 formulas ATIVAS com esses slugs.
--   1. Backup em private.formula_compositions_backup_20260922 (linhas ativas das 24) e
--      private.formulas_backup_20260922 (campos de formulas que serao alterados).
--   2. Insumos novos em public.ingredients (6), on conflict (slug) do nothing.
--   3. Exclusao LOGICA das composicoes ativas das 23 formulas reformuladas (nao do Omega).
--   4. Insercao das 201 linhas harmonizadas, ingredient_id resolvido por slug.
--   5. Update de formulas (ingredients_list, warnings, nutritional_info, serving_description, metadata) nas 24.
--   6. Autocheck: contagem por formula, nenhuma linha antiga sobrevivente, nenhum ingredient_id nulo,
--      total = 201 nas 23; Omega intocado.
--   7. Zera compliance_verified_at / compliance_norms / compliance_source das 24 (selo a reavaliar).
--
-- IDEMPOTENTE: re-execucao nao duplica (exclusao so de linhas sem metadata.fonte = 'reformulacao_2026-09-16';
-- insercao so em formula sem linha ativa dessa fonte; backups pulam ids ja copiados; updates por valor).
--
-- REVERSAO (manual): reativar as linhas de private.formula_compositions_backup_20260922 pelo id e desativar as
-- linhas com metadata->>'fonte' = 'reformulacao_2026-09-16'; restaurar os campos de formulas pelo backup.
--
-- APLICACAO: arquivo criado em disco em 16/09/2026; NAO aplicado em nenhum banco. Sintaxe conferida com pglast
-- (libpg_query) sem execucao.
-- =====================================================================================

-- -------------------------------------------------------------------------------------
-- 0. GUARDA - as 24 formulas precisam existir, ativas, pelo slug
-- -------------------------------------------------------------------------------------
do $$
declare
    v_encontradas integer;
begin
    select count(*) into v_encontradas
    from public.formulas
    where deleted_at is null and active and slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
          'detox-matinal-lemon-shot-300g',
          'saude-intestinal',
          'moro-slim',
          'pro-energy',
          'emagrecedor-em-capsula',
          'slim-up-emagrecimento-em-gota',
          'shot-colageno-300-gramas',
          'omega-pro-tg',
          'bella-gummy-biotina-em-gummy',
          'creatina-monohidratada-150g-soluvel',
          'creatina-monohidratada-300g-soluvel',
          'creatina-gummy-sabor-frutas-vermelhas',
          'creatina-em-gummy-sabor-tutti-frutti',
          'melatonina-em-gummy-sabor-uva',
          'pre-treino-300-g',
          'pre-treino-creatina-sabor-limao-420g'
      );
    if v_encontradas <> 24 then
        raise exception 'esperado 24 formulas ativas com os slugs desta migration, encontrado %', v_encontradas;
    end if;
end $$;

-- -------------------------------------------------------------------------------------
-- 1. BACKUP (schema private, fora da API) - mesmo estilo da 20260920000000
-- -------------------------------------------------------------------------------------
create table if not exists private.formula_compositions_backup_20260922 as
select fc.*, now() as backed_up_at from public.formula_compositions fc where false;
comment on table private.formula_compositions_backup_20260922 is 'Copia das linhas ativas de public.formula_compositions das 24 formulas antes da migration 20260922000000_reformulacao_conforme_normas.sql. Serve para reverter. Nao exposta pela API.';

insert into private.formula_compositions_backup_20260922
select fc.*, now()
from public.formula_compositions fc
join public.formulas f on f.id = fc.formula_id
where f.deleted_at is null and fc.deleted_at is null
  and f.slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
          'detox-matinal-lemon-shot-300g',
          'saude-intestinal',
          'moro-slim',
          'pro-energy',
          'emagrecedor-em-capsula',
          'slim-up-emagrecimento-em-gota',
          'shot-colageno-300-gramas',
          'omega-pro-tg',
          'bella-gummy-biotina-em-gummy',
          'creatina-monohidratada-150g-soluvel',
          'creatina-monohidratada-300g-soluvel',
          'creatina-gummy-sabor-frutas-vermelhas',
          'creatina-em-gummy-sabor-tutti-frutti',
          'melatonina-em-gummy-sabor-uva',
          'pre-treino-300-g',
          'pre-treino-creatina-sabor-limao-420g'
      )
  and coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16'
  and not exists (select 1 from private.formula_compositions_backup_20260922 b where b.id = fc.id);

create table if not exists private.formulas_backup_20260922 as
select f.id, f.slug, f.ingredients_list, f.warnings, f.nutritional_info, f.serving_description, f.metadata,
       f.compliance_verified_at, f.compliance_norms, f.compliance_source, now() as backed_up_at
from public.formulas f where false;
comment on table private.formulas_backup_20260922 is 'Copia dos campos de public.formulas alterados pela migration 20260922000000 (dizeres, tabela nutricional, porcao, metadata e selo de conformidade) das 24 formulas, antes da alteracao.';

insert into private.formulas_backup_20260922
select f.id, f.slug, f.ingredients_list, f.warnings, f.nutritional_info, f.serving_description, f.metadata,
       f.compliance_verified_at, f.compliance_norms, f.compliance_source, now()
from public.formulas f
where f.deleted_at is null and f.slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
          'detox-matinal-lemon-shot-300g',
          'saude-intestinal',
          'moro-slim',
          'pro-energy',
          'emagrecedor-em-capsula',
          'slim-up-emagrecimento-em-gota',
          'shot-colageno-300-gramas',
          'omega-pro-tg',
          'bella-gummy-biotina-em-gummy',
