-- -------------------------------------------------------------------------------------
-- 3. EXCLUSAO LOGICA das composicoes ativas atuais das 23 formulas reformuladas (Omega fica)
-- -------------------------------------------------------------------------------------
update public.formula_compositions fc
set active = false, deleted_at = now(), reason_deleted = 'reformulação regulatória 2026-09-16'
from public.formulas f
where f.id = fc.formula_id and f.deleted_at is null
  and f.slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
          'detox-matinal-lemon-shot-300g',
          'saude-intestinal',
          'moro-slim',
          'pro-energy',
          'emagrecedor-em-capsula',
          'slim-up-emagrecimento-em-gota',
          'shot-colageno-300-gramas',
          'bella-gummy-biotina-em-gummy',
          'creatina-monohidratada-150g-soluvel',
          'creatina-monohidratada-300g-soluvel',
          'creatina-gummy-sabor-frutas-vermelhas',
          'creatina-em-gummy-sabor-tutti-frutti',
          'melatonina-em-gummy-sabor-uva',
          'pre-treino-300-g',
          'pre-treino-creatina-sabor-limao-420g'
      )
  and fc.deleted_at is null
  and coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16';

