    ('pre-treino-creatina-sabor-limao-420g', 17, 'Maltodextrina', 2275.3575, 'mg', 'maltodextrina', '{"fonte": "reformulacao_2026-09-16","papel": "veiculo","ins": null,"massa_mg": 2275.3575,"laudo_lote": null,"observacao": "veículo q.s.p. 14.000 mg; laudo lote 210170 VENCIDO. Recalculado na fase 3 (era 2.268,091) após as massas harmonizadas de bisglicinato de magnésio (992,72 mg), vitamina D3 (13,913 mg) e metilcobalamina (0,009522 mg): 14.000 − 10.066,6425 − 1.658","nome_no_memorial": "Maltodextrina"}')
) as v(slug, sort_order, ingredient_name, quantity, unit, ingredient_slug, metadata)
join public.formulas f on f.slug = v.slug and f.deleted_at is null
join public.ingredients i on i.slug = v.ingredient_slug and i.deleted_at is null
where not exists (
    select 1 from public.formula_compositions x
    where x.formula_id = f.id and x.deleted_at is null and x.metadata->>'fonte' = 'reformulacao_2026-09-16'
);

