Conservar em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C. Após aberto, consumir em até 60 dias. Não consumir se o lacre de segurança estiver violado.',
    serving_description = '1 g (2 cápsulas)',
    metadata            = coalesce(f.metadata, '{}'::jsonb) - 'tabela_nutricional_2026_09_16' - 'tabela_nutricional_20260916' - 'reformulacao' || jsonb_build_object('reformulacao_2026_09_16', '{"data": "2026-09-16","fonte": "fase 3 - consolidacao de docs/conformidade/reformulacao/multivitaminico.md","veredito": "CONFORME CONDICIONADO A (laudo de óxido de magnésio; aquisição de fonte de boro autorizada com laudo; laudos de selenito de sódio e bisglicinato de cobre; laudo vigente da menaquinona-7 do lote em uso; confirmação da potência da vitamina A)","grupo_populacional": "adultos, coluna \"> 19 anos\" dos Anexos III e IV","porcao_mg": 1000.0,"porcao_descricao": "1 g (2 cápsulas)","formato": "cápsula gelatinosa dura, tamanho 0 (memorial rev02)","soma_porcao_mg": 999.9997,"cabe": true,"linhas_composicao": 19,"tabela_nutricional": {"porcoes_por_embalagem": "30","porcao": "1 g (2 cápsulas)","grupos_vd": ["adultos_19_anos_ou_mais"],"linhas": [{"item": "Valor energético","quantidade": 0.0,"unidade": "kcal","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false,"kj": 0.0,"kcal_exato": 0.0},{"item": "Carboidratos","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares totais","quantidade": 0.0,"unidade": "g","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares adicionados","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 2,"nota": null,"pendente": false,"provisorio": false},{"item": "Proteínas","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras totais","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras saturadas","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras trans","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Fibras alimentares","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Sódio","quantidade": 3.2,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina A","quantidade": 1300.0,"unidade": "µg RAE","vd_pct": {"adultos_19_anos_ou_mais": 163},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina D","quantidade": 40.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 267},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina E","quantidade": 10.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 67},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina K","quantidade": 120.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": "teor de laudo VENCIDO (lote PURI011426 (Gemini/Purifarma, fabricante 2003D04) — único laudo de MK-7 na máquina, validade 24/03/2022) — pedir laudo novo e recalcular a massa pelo teor","pendente": false,"provisorio": true},{"item": "Vitamina C","quantidade": 100.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Tiamina","quantidade": 1.2,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Riboflavina","quantidade": 1.3,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 108},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Niacina","quantidade": 16.0,"unidade": "mg NE","vd_pct": {"adultos_19_anos_ou_mais": 107},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina B6","quantidade": 1.3,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Ácido fólico","quantidade": 1000.0,"unidade": "µg DFE","vd_pct": {"adultos_19_anos_ou_mais": 250},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Ácido pantotênico","quantidade": 5.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina B12","quantidade": 8.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 333},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Cobre","quantidade": 900.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Cromo","quantidade": 35.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Magnésio","quantidade": 260.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 62},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Selênio","quantidade": 100.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 167},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Zinco","quantidade": 15.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 136},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Boro","quantidade": 3.0,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": null,"pendente": false,"provisorio": false}],"rodape": "*Percentual de valores diários fornecidos pela porção","regras": "Arredondamento: Anexo III da IN 75/2020 (paráfrase do gabarito de 16/09/2026). %VD: Anexo VIII da IN 75/2020 para o grupo do rótulo (macronutrientes: Anexo II), calculado sobre a quantidade declarada. Quantidade não significativa (Anexo IV): %VD 0. Sem VDR: célula em branco (RDC 429/2020, art. 12, §1º). Energia: fatores do Anexo XXII da IN 75 (kcal/g); kJ = kcal × 4,184.","provisoria": true},"advertencias_anexo_vi": [["Boro","Este produto não deve ser consumido por gestantes, lactantes e crianças."]],"pendencias": ["Comprar **óxido de magnésio** (grau alimentício/USP) e obter laudo com teor de Mg antes de pesar — a massa de 431,15 mg foi calculada com 60,30% (MgO puro) e deve ser recalculada pelo teor do laudo.","Comprar a **fonte de boro** autorizada: tetraborato de sódio decahidratado (massa estequiométrica 26,46 mg para 3 mg de B) ou frutoborato de cálcio (massa a definir pelo teor do laudo do fabricante). Nenhum laudo de nenhuma das duas existe na máquina. Decisão do dono: a alternativa é retirar o boro (o Multivitamínico não depende dele).","Comprar **selenito de sódio** e **bisglicinato de cobre** com laudo (ou ficha do fabricante NaturalPRO declarando que o ''cobre aminoácido quelato'' é bisglicinato de cobre, CAS 13479-54-4 — sem isso não serve). Microdoses de selenito (0,22 mg) exigem pré-mistura definida pela fábrica.","Obter **laudo vigente da menaquinona-7** realmente em uso (lote não identificado no memorial rev02). A massa de 8,11 mg é provisória, calculada com o único teor conhecido (1,48%, laudo vencido). Sem laudo, a vitamina K2 não pode ser declarada.","**L-teanina — decisão do dono:** rota A (retirar, proposta principal deste memorial) ou rota B (manter 150 mg comprando \"L-teanina de folhas de Camellia sinensis\" — especificação aprovada: fabricante Blue California, segundo o painel da ANVISA lido em 15/09 — como insumo a adquirir). O lote AUTO039250 em estoque não pode ser usado em nenhuma das rotas.","**Vitamina A:** o laudo do lote 215230 é digitalização; a potência de 568.116 UI/g vem do memorial rev02 e é 13,6% acima do nominal (500.000 UI/g) — confirmar com o fornecedor antes de fixar a massa.","**Excipiente:** com a teanina fora e o óxido no lugar do bisglicinato, o dióxido de silício q.s.p. chega a 277 mg (27,7% da porção). Decisão do RT: manter (quantum satis) ou usar agente de massa (ex.: celulose microcristalina, já declarada no rótulo do Focus Colina) com antiumectante em 1–2% — a conferência do agente de massa na IN 211/2023 não foi feita nesta etapa.","**Rótulo:** trocar ''bisglicinato de magnésio'' por ''óxido de magnésio'' (inclusive na chamada principal da arte, que hoje diz ''magnésio bisglicinato''); trocar ''quelato de boro'' por ''tetraborato de sódio decahidratado''; ''cianocobalamina'' por ''metilcobalamina''; retirar ''L-teanina''; atualizar ácido fólico (600 µg), K2 (120 µg), D3 (40 µg) e B12 (8 µg); refazer a tabela nutricional conforme a seção 5.","\"Não contém glúten\": manter só com laudo de glúten do produto acabado.","Vitamina B1: confirmar com o RT a convenção de declaração (tiamina base, como proposto, ou como cloridrato); as duas leituras ficam dentro da faixa 0,18–2,02 mg."],"alternativas": ["**Magnésio via bisglicinato, dose reduzida:** manter bisglicinato de magnésio 30% (laudo novo do lote em estoque ou lote novo) e baixar o Mg para 150 mg (496,4 mg de sal a 30,22%); a fórmula fecha em ~787 mg + excipiente. Mantém a chamada ''bisglicinato'' do rótulo, mas muda o número de 260 para 150 mg.","**Rota B da L-teanina:** manter 150 mg como \"L-teanina de folhas de Camellia sinensis\" (insumo a adquirir); a soma sobe para ~872 mg + excipiente e a advertência genérica ganha o lastro adicional da linha \"Aminoácidos\" do Anexo VI. Veredito ficaria condicionado também a esse laudo de origem.","**Retirar o boro** em vez de comprar a fonte autorizada: elimina uma aquisição e a advertência do Anexo VI passaria a não ser exigida por nenhum constituinte (a frase poderia sair do rótulo)."],"mudancas": ["Magnésio: bisglicinato de magnésio (860,36 mg, laudo vencido) → óxido de magnésio 431,15 mg, mesma dose de 260 mg — motivo: a porção de 1 g não comporta 860 mg de sal (Anexo I autoriza \"Óxido de magnésio\", CAS 1309-48-4). Insumo a adquirir, laudo pendente.","Boro: ''quelato de boro (glicinato)'' → tetraborato de sódio decahidratado, 3 mg de boro — motivo: forma não listada no Anexo I (linhas \"Frutoborato de cálcio\" e \"Tetraborato de sódio decahidratado\" são as únicas). Insumo a adquirir.","Selênio: glicinato de selênio (pesado) → selenito de sódio (que o rótulo já imprime), 100 µg — motivo: forma não listada no Anexo I (linha \"Selenito de sódio\"). Insumo a adquirir.","Cobre: ''cobre aminoácido quelato 24%'' → bisglicinato de cobre (que o rótulo já imprime), 900 µg — motivo: forma não identificada entre as 5 do Anexo I. Insumo a adquirir.","Ácido fólico: 800 → 600 µg (1.333 → 1.000 µg DFE) — motivo: Anexo IV, teto 1.281,5 µg DFE (nota iv), com folga de 22%.","Vitamina K2: 149 → 120 µg — motivo: 149 µg cravava o teto de 149,06 µg; e a massa passa a considerar o teor real do pré-mix (1,48%), não 100%.","Vitamina D3: 50 → 40 µg — motivo: teto exato de 50 µg sem folga de fabricação.","Vitamina B12: 9,94 → 8 µg — motivo: teto exato de 9,94 µg; insumo real é metilcobalamina (rótulo diz cianocobalamina — corrigir).","Vitamina B1: fixada em 1,2 mg (rótulo) com massa recalculada pelo teor real do laudo 91454 (99,8%) e fator sal→base — motivo: o memorial rev02 pesava 2,4 mg com teor ''a confirmar'', o que entregaria 2,395 mg, acima do teto de 2,02 mg.","L-teanina: retirada (rota A) — motivo: só a de folhas de Camellia sinensis é autorizada e o laudo do lote em uso prova síntese química.","Vitamina C, zinco, niacina, vitamina E, ácido pantotênico, B6, B2, vitamina A e cromo: mantidos nas doses do rótulo (todos entre o mínimo e 90% do teto; laudos válidos, exceto vitamina A cujo laudo é digitalização lida só pelo memorial)."],"removidos": [{"constituinte": "Teanina","quantidade_mg": 150,"motivo": "origem não comprovada (laudo: síntese química); só ''L-teanina de folhas de Camellia sinensis'' é autorizada — rota A"}]}'::jsonb)
where f.slug = 'multivitaminico' and f.deleted_at is null;

-- zma-zinco-magnesio-e-vitamina-d: CONFORME CONDICIONADO
update public.formulas f set
    ingredients_list    = 'Bisglicinato de magnésio, antiumectante dióxido de silício (INS 551), L-teanina de folhas de Camellia sinensis, bisglicinato de zinco, tetraborato de sódio decahidratado, colecalciferol (vitamina D3), cloridrato de piridoxina (vitamina B6) e cápsula: gelatina, água purificada e corante dióxido de titânio (INS 171).',
    nutritional_info    = 'INFORMAÇÃO NUTRICIONAL
Porções por embalagem: 30
