Conservar em local seco, fresco e arejado, ao abrigo da luz e do calor excessivo, em temperatura ambiente entre 15 °C e 30 °C. Após aberto, consumir em até 60 dias. Não consumir se o lacre de segurança estiver violado.',
    serving_description = '1 g (2 cápsulas)',
    metadata            = coalesce(f.metadata, '{}'::jsonb) - 'tabela_nutricional_2026_09_16' - 'tabela_nutricional_20260916' - 'reformulacao' || jsonb_build_object('reformulacao_2026_09_16', '{"data": "2026-09-16","fonte": "fase 3 - consolidacao de docs/conformidade/reformulacao/dores-musculares.md","veredito": "CONFORME CONDICIONADO A (ficha do fabricante do colágeno tipo II; identidade do ferro; laudos de óxido de magnésio e selenito de sódio; declaração de origem da glucosamina)","grupo_populacional": "adultos, coluna \"> 19 anos\" dos Anexos III e IV","porcao_mg": 1000.0,"porcao_descricao": "1 g (2 cápsulas)","formato": "cápsula gelatinosa dura, tamanho 0 (memorial rev02)","soma_porcao_mg": 1000.0,"cabe": true,"linhas_composicao": 13,"tabela_nutricional": {"porcoes_por_embalagem": "30","porcao": "1 g (2 cápsulas)","grupos_vd": ["adultos_19_anos_ou_mais"],"linhas": [{"item": "Valor energético","quantidade": 0.1,"unidade": "kcal","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false,"kj": 0.5,"kcal_exato": 0.1082},{"item": "Carboidratos","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares totais","quantidade": 0.0,"unidade": "g","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares adicionados","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 2,"nota": null,"pendente": false,"provisorio": false},{"item": "Proteínas","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras totais","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras saturadas","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras trans","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Fibras alimentares","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Sódio","quantidade": 0.06,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina D","quantidade": 40.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 267},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina E","quantidade": 20.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 133},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina C","quantidade": 140.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 140},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina B6","quantidade": 1.3,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina B12","quantidade": 8.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 333},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Ferro","quantidade": 8.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 57},"nivel": 0,"nota": "teor PROVISÓRIO: laudo","pendente": false,"provisorio": true},{"item": "Magnésio","quantidade": 70.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 17},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Selênio","quantidade": 100.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 167},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Zinco","quantidade": 10.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 91},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Metilsulfonilmetano","quantidade": 250.0,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Glucosamina","quantidade": 118.0,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Colágeno tipo II não desnaturado","quantidade": 40.0,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": "mantido — PENDENTE identidade: 40 mg (33× o mínimo). O Anexo I autoriza duas coisas distintas: ''Colágeno Tipo II'' em Proteínas (mín. 8,4 g) e ''colágeno de frango com colágeno tipo II não desnaturado'' (mín. 1,2 mg). O produto só é c","pendente": false,"provisorio": true}],"rodape": "*Percentual de valores diários fornecidos pela porção","regras": "Arredondamento: Anexo III da IN 75/2020 (paráfrase do gabarito de 16/09/2026). %VD: Anexo VIII da IN 75/2020 para o grupo do rótulo (macronutrientes: Anexo II), calculado sobre a quantidade declarada. Quantidade não significativa (Anexo IV): %VD 0. Sem VDR: célula em branco (RDC 429/2020, art. 12, §1º). Energia: fatores do Anexo XXII da IN 75 (kcal/g); kJ = kcal × 4,184.","provisoria": true},"advertencias_anexo_vi": [["Glucosamina","Este produto não deve ser consumido por gestantes, lactantes e crianças. Pessoas com enfermidades e/ou sob o uso de medicamentos, consulte seu médico."]],"pendencias": ["**Colágeno tipo II — ficha do fabricante (via Lepuge):** origem (frango, esterno), forma não desnaturada, nome do fabricante e doseamento. Sem isso o constituinte não pode ser afirmado como ''colágeno de frango com colágeno tipo II não desnaturado'' e deve sair. O laudo vence em 06/11/2026.","**Ferro — identidade química:** obter da NaturalPRO a declaração de que ''Quelato Ferro Bios 20%'' é bisglicinato ferroso (CAS 20150-34-9); senão comprar bisglicinato ferroso com laudo (os da máquina venceram em 2022/2023).","**Comprar óxido de magnésio e selenito de sódio** com laudo; recalcular massas pelo teor.","**Cálcio — decisão do dono:** retirado nesta proposta. Alternativa: manter cálcio só se a porção subir para 3 cápsulas (ver alternativas).","**Glucosamina — origem:** pedir ao fabricante (TSM, via SM Empreendimentos) a declaração de origem (crustáceo ou fermentação); enquanto não vier, declarar ''contém crustáceos''.","**Lactose:** conferir com o RT a obrigação de declaração (RDC 135/2017) diante do ''pode conter lactose'' do laudo do colágeno tipo II.","**MSM:** conferir lote em estoque (950413 ou 222159) — massa muda 1,9 mg.","**Rótulo:** corrigir ''colecalciferol 50 mg / 1000%'' na tabela (correto: 40 µg / 267%); declarar magnésio (70 mg) e retirar cálcio e colágeno hidrolisado; nomear ''acetato de DL-alfa-tocoferol''; declarar glucosamina (118 mg) e a forma completa; declarar zinco e ferro como elementos; alergênicos; advertência completa da glucosamina."],"alternativas": ["**3 cápsulas por porção (1,5 g):** permitiria manter cálcio a 200 mg (527,4 mg de carbonato de cálcio a 37,92%, laudo válido 950403) com o óxido de magnésio — soma ≈ 1.438 mg + 62 mg de excipiente (4,2%). Com bisglicinato de magnésio no lugar do óxido (231,6 mg) a soma iria a ≈ 1.553 mg e não caberia nem em 3 cápsulas. Mudança de porção é decisão do dono.","**Magnésio via bisglicinato em 2 cápsulas:** só cabe se o MSM cair para ~150 mg; não proposto porque muda o ativo principal.","**L-selenometionina** em vez de selenito (forma também autorizada) — exige compra com laudo que declare a forma."],"mudancas": ["Colágeno hidrolisado 100 mg: retirado — mínimo de 8,4 g (Anexo III, Proteínas).","Carbonato de cálcio 100 mg: retirado — 37,9 mg de Ca contra 180 mg de mínimo; a massa para o mínimo (≥ 475 mg de carbonato) não cabe em 1 g.","Magnésio: bisglicinato 100 mg (30,22 mg de Mg, laudo vencido) → óxido de magnésio 116,08 mg (70 mg de Mg) — motivo: mínimo de 63 mg (Anexo III) com folga de 11%; o bisglicinato para 70 mg pesaria 231,6 mg e não caberia. Insumo a adquirir.","Selênio: ''selênio quelado'' (glicinato) → selenito de sódio, 100 µg — forma do Anexo I. Insumo a adquirir.","Glucosamina: nome completo do Anexo I (''sulfato de glucosamina com cloreto de potássio'') e declaração do ativo (118 mg de glucosamina); alergênico crustáceo declarado.","Colágeno tipo II: mantido a 40 mg, condicionado à ficha do fabricante (origem frango, forma não desnaturada) — sem ela, retirar; alergênicos do laudo (''pode conter leite, lactose e peixe'') declarados.","Ferro: 8 mg de ferro elemento (declaração corrigida); insumo condicionado à declaração de identidade (bisglicinato ferroso) do fabricante NaturalPRO ou à compra de bisglicinato ferroso com laudo.","Zinco: declarado como elemento (10 mg) — a composição dizia ''bisglicinato de zinco 10 mg''.","MSM: fixado no valor do rótulo (250 mg) — o memorial pesa 350 e o cadastro diz 480,5.","Vitamina D3 50 → 40 µg e vitamina B12 9,94 → 8 µg — teto exato sem folga; corrigir ''50 mg''/''1000%'' da tabela do rótulo.","Vitamina E: nome do insumo corrigido para acetato de DL-alfa-tocoferol (20 mg de α-tocoferol).","Vitamina C e B6: mantidas."],"removidos": [{"constituinte": "Proteínas (colágeno hidrolisado)","quantidade_mg": 100,"motivo": "abaixo do mínimo de 8,4 g"},{"constituinte": "Cálcio (carbonato de cálcio)","quantidade_mg": 100,"motivo": "37,9 mg de Ca contra mínimo de 180 mg; 527 mg de carbonato não cabem na porção"}]}'::jsonb)
where f.slug = 'dores-musculares' and f.deleted_at is null;

