    metadata            = coalesce(f.metadata, '{}'::jsonb) - 'tabela_nutricional_2026_09_16' - 'tabela_nutricional_20260916' - 'reformulacao' || jsonb_build_object('reformulacao_2026_09_16', '{"data": "2026-09-16","fonte": "fase 3 - consolidacao de docs/conformidade/reformulacao/focus-colina.md","veredito": "CONFORME CONDICIONADO A (laudo de origem Camellia sinensis da L-teanina nova; laudo de óxido de magnésio) — com a decisão do dono sobre a dose de colina (130 mg em 2 cápsulas)","grupo_populacional": "adultos, coluna \"> 19 anos\" dos Anexos III e IV","porcao_mg": 1000.0,"porcao_descricao": "1 g (2 cápsulas)","formato": "cápsula gelatinosa dura, tamanho 0 (memorial rev02)","soma_porcao_mg": 1000.0001,"cabe": true,"linhas_composicao": 10,"tabela_nutricional": {"porcoes_por_embalagem": "30","porcao": "1 g (2 cápsulas)","grupos_vd": ["adultos_19_anos_ou_mais"],"linhas": [{"item": "Valor energético","quantidade": 1.7,"unidade": "kcal","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false,"kj": 7.0,"kcal_exato": 1.68},{"item": "Carboidratos","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares totais","quantidade": 0.0,"unidade": "g","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares adicionados","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 2,"nota": null,"pendente": false,"provisorio": false},{"item": "Proteínas","quantidade": 0.4,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Tirosina","quantidade": 290.0,"unidade": "mg","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras totais","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras saturadas","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras trans","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Fibras alimentares","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Sódio","quantidade": 0.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina D","quantidade": 5.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 33},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina B6","quantidade": 1.3,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina B12","quantidade": 2.4,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 100},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Magnésio","quantidade": 70.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 17},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Colina","quantidade": 130.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 24},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "L-Carnitina","quantidade": 95.0,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Teanina","quantidade": 115.0,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": "forma trocada (origem) — PENDENTE laudo: dose do rótulo (46% do teto) mantida; a origem tem de ser a de folhas de Camellia sinensis (única do Anexo I). Rota A (retirar) na seção 8 — para um produto de ''foco'', a teanina é parte do conceito.","pendente": false,"provisorio": true},{"item": "Inositol","quantidade": 25.0,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": null,"pendente": false,"provisorio": false}],"rodape": "*Percentual de valores diários fornecidos pela porção","regras": "Arredondamento: Anexo III da IN 75/2020 (paráfrase do gabarito de 16/09/2026). %VD: Anexo VIII da IN 75/2020 para o grupo do rótulo (macronutrientes: Anexo II), calculado sobre a quantidade declarada. Quantidade não significativa (Anexo IV): %VD 0. Sem VDR: célula em branco (RDC 429/2020, art. 12, §1º). Energia: fatores do Anexo XXII da IN 75 (kcal/g); kJ = kcal × 4,184.","provisoria": true},"advertencias_anexo_vi": [["Aminoácidos; Carnitina; Inositol","Este produto não deve ser consumido por gestantes, lactantes e crianças."]],"pendencias": ["**Porção — decisão do dono:** com 2 cápsulas, a colina cai de 470 para 130 mg (o nome do produto é ''Focus Colina''). Alternativas: 3 cápsulas (colina ≈ 290 mg) ou 4 cápsulas (colina 470 mg, como o rótulo) — ver alternativas. A fábrica já desenhou uma versão em pó solúvel (5 g e 10 g por dose) com tirosina e magnésio nos mínimos exatos — outra saída.","**L-teanina — decisão do dono:** rota B (proposta: comprar a de folhas de Camellia sinensis, especificação Blue California, com laudo de origem) ou rota A (retirar; libera 115 mg para a colina, que subiria para ~180 mg).","**Comprar óxido de magnésio** com laudo (recalcular 116,08 mg pelo teor).","**Vitamina B12:** confirmar no corpo do laudo 219376 a umidade (9,07%) que o memorial usa; o rótulo deve passar de ''cianocobalamina'' para ''metilcobalamina''.","**Rótulo:** atualizar colina (130 mg), tirosina (290 mg), magnésio (70 mg, óxido); nomear ''L-teanina de folhas de Camellia sinensis''; retirar ''celulose microcristalina''; declarar colina, tirosina, teanina, carnitina e inositol na tabela nutricional (o rótulo vigente só lista Mg, B6, B12 e D); confirmar lauril sulfato de sódio na cápsula."],"alternativas": ["**3 cápsulas por porção (1,5 g):** mesmos ativos com colina 290 mg (714,1 mg de bitartarato); soma ≈ 1.363 mg + 137 mg de excipiente. Mudança de porção é decisão do dono.","**4 cápsulas por porção (2 g):** colina 470 mg como no rótulo (1.157,35 mg de bitartarato); soma ≈ 1.806 mg + 194 mg de excipiente — a única forma de manter os 470 mg em cápsula.","**Magnésio via bisglicinato de magnésio** (231,6 mg a 30,22%, laudo novo) em vez do óxido: cabe só se a colina cair para ~90 mg em 2 cápsulas.","**Rota A da L-teanina (retirar):** colina sobe para ~180 mg em 2 cápsulas (446 mg de bitartarato); veredito condicionado só ao óxido de magnésio."],"mudancas": ["Colina: 470 → 130 mg (bitartarato 1.157,35 → 320,12 mg) — motivo: a fórmula do memorial soma 1.818,30 mg para uma porção de 1.000 mg; só a colina em bitartarato já ultrapassa a porção. 130 mg é o máximo que cabe em 2 cápsulas com os demais ativos e 3% de excipiente; continua acima do mínimo de 82,5 mg (Anexo III).","L-tirosina: 220 → 290 mg — motivo: mínimo de 262,5 mg (Anexo III, nota viii), com folga de 10%.","Magnésio: bisglicinato 198,54 mg (60 mg de Mg, laudo vencido) → óxido de magnésio 116,08 mg (70 mg de Mg) — motivo: mínimo de 63 mg com folga; o bisglicinato não cabe. Insumo a adquirir.","L-teanina: origem sintética → \"L-teanina de folhas de Camellia sinensis\", 115 mg — motivo: Anexo I (IN 318/2024). Insumo a adquirir (rota B).","Vitamina B12: nome corrigido para metilcobalamina (insumo pesado) e massa recalculada com o teor do lote 219376 (89,27%) — motivo: o §6.1 do memorial usou 94,54%, de outro lote.","L-carnitina, inositol, B6 e D3: mantidos.","Celulose microcristalina (agente de massa do rótulo): retirada — sem função com a fórmula em 96,9% da porção."],"removidos": []}'::jsonb)
where f.slug = 'focus-colina' and f.deleted_at is null;

