    serving_description = '1 g (2 cápsulas)',
    metadata            = coalesce(f.metadata, '{}'::jsonb) - 'tabela_nutricional_2026_09_16' - 'tabela_nutricional_20260916' - 'reformulacao' || jsonb_build_object('reformulacao_2026_09_16', '{"data": "2026-09-16","fonte": "fase 3 - consolidacao de docs/conformidade/reformulacao/multi-vitta-gestante-e-lactante-em-capsula.md","veredito": "CONFORME CONDICIONADO A (laudo novo do bisglicinato de magnésio; laudos de bisglicinato ferroso e bisglicinato de cobre; emissão do memorial de cálculo pelo RT) — e à decisão do dono sobre completar ou não os nutrientes citados sem dose","grupo_populacional": "gestantes e lactantes — colunas \"Gestantes\" e \"Lactantes\" dos Anexos III e IV, aplicada a mais restritiva das duas a cada constituinte (mínimo = maior dos mínimos; máximo = menor dos máximos)","porcao_mg": 1000.0,"porcao_descricao": "1 g (2 cápsulas)","formato": "cápsula (sem memorial: tamanho e capacidade não registrados; assumida a mesma cápsula tamanho 0 de 500 mg de pó dos demais produtos da linha)","soma_porcao_mg": 999.9997,"cabe": true,"linhas_composicao": 12,"tabela_nutricional": {"porcoes_por_embalagem": "30","porcao": "1 g (2 cápsulas)","grupos_vd": ["gestantes","lactantes"],"linhas": [{"item": "Valor energético","quantidade": 0.0,"unidade": "kcal","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false,"kj": 0.0,"kcal_exato": 0.0},{"item": "Carboidratos","quantidade": 0.0,"unidade": "g","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares totais","quantidade": 0.0,"unidade": "g","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares adicionados","quantidade": 0.0,"unidade": "g","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 2,"nota": null,"pendente": false,"provisorio": false},{"item": "Proteínas","quantidade": 0.0,"unidade": "g","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras totais","quantidade": 0.0,"unidade": "g","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras saturadas","quantidade": 0.0,"unidade": "g","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras trans","quantidade": 0.0,"unidade": "g","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Fibras alimentares","quantidade": 0.0,"unidade": "g","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Sódio","quantidade": 0.0,"unidade": "mg","vd_pct": {"gestantes": 0,"lactantes": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina D","quantidade": 40.0,"unidade": "µg","vd_pct": {"gestantes": 267,"lactantes": 267},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina E","quantidade": 5.0,"unidade": "mg","vd_pct": {"gestantes": 33,"lactantes": 33},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina C","quantidade": 20.0,"unidade": "mg","vd_pct": {"gestantes": 24,"lactantes": 17},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Niacina","quantidade": 8.0,"unidade": "mg NE","vd_pct": {"gestantes": "PENDENTE","lactantes": "PENDENTE"},"nivel": 0,"nota": "VD de niacina para este grupo não extraído do Anexo VIII (pendência do gabarito)","pendente": false,"provisorio": false},{"item": "Ácido fólico","quantidade": 833.0,"unidade": "µg DFE","vd_pct": {"gestantes": 139,"lactantes": 167},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Ácido pantotênico","quantidade": 4.5,"unidade": "mg","vd_pct": {"gestantes": 75,"lactantes": 64},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Vitamina B12","quantidade": 8.0,"unidade": "µg","vd_pct": {"gestantes": 308,"lactantes": 286},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Cálcio","quantidade": 215.0,"unidade": "mg","vd_pct": {"gestantes": 17,"lactantes": 17},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Cobre","quantidade": 900.0,"unidade": "µg","vd_pct": {"gestantes": 90,"lactantes": 69},"nivel": 0,"nota": "mantido — PENDENTE laudo: dose do cadastro (13,0% do teto). O cadastro já nomeia bisglicinato de cobre; não há laudo dessa forma na máquina (só ''cobre aminoácido quelato'' NaturalPRO, forma não identificada, e gluconato de cobr","pendente": false,"provisorio": true},{"item": "Ferro","quantidade": 8.1,"unidade": "mg","vd_pct": {"gestantes": 30,"lactantes": 81},"nivel": 0,"nota": "teor PROVISÓRIO: laudo NaturalPRO NPT.0525/710 (Fe 20,1 %; identidade química não declarada) — harmonizado na fase 3 com o Dores Musculares","pendente": false,"provisorio": true},{"item": "Magnésio","quantidade": 66.0,"unidade": "mg","vd_pct": {"gestantes": 17,"lactantes": 18},"nivel": 0,"nota": "teor de laudo VENCIDO (lote 90844 (Analitic, fabricante 66342023062230), validade 21/06/2025) — pedir laudo novo e recalcular a massa pelo teor","pendente": false,"provisorio": true}],"rodape": "*Percentual de valores diários fornecidos pela porção","regras": "Arredondamento: Anexo III da IN 75/2020 (paráfrase do gabarito de 16/09/2026). %VD: Anexo VIII da IN 75/2020 para o grupo do rótulo (macronutrientes: Anexo II), calculado sobre a quantidade declarada. Quantidade não significativa (Anexo IV): %VD 0. Sem VDR: célula em branco (RDC 429/2020, art. 12, §1º). Energia: fatores do Anexo XXII da IN 75 (kcal/g); kJ = kcal × 4,184.","provisoria": true},"advertencias_anexo_vi": [],"pendencias": ["**Composição — decisão do dono:** a lista de ingredientes do cadastro cita vitamina A, K2, complexo B, biotina, cromo e selênio que não têm quantidade em lugar nenhum (nem memorial, nem ficha, nem rótulo existem). Esta proposta só formula o que está cadastrado com quantidade. Se o dono quiser completar o multivitamínico pré-natal, as faixas a respeitar (mais restritiva entre gestantes e lactantes, Anexos III/IV) são: vitamina A 195–2.414,35 µg RAE (só pré-formada; o iodo, importante para o grupo, teria faixa 43,5–717,56 µg); vitamina K 13,5–126,02 µg; tiamina 0,21–1,93 mg; riboflavina 0,24–2,66 mg; B6 0,3–78,59 mg; biotina 5,25–45 µg; cromo 6,75–45 µg; selênio 10,5–309,65 µg; zinco 1,95–23,50 mg; iodo 43,5–717,56 µg. Manganês e boro são ''NA'' para os dois grupos — não podem entrar.","**Laudo novo de bisglicinato de magnésio** (ou trocar por óxido de magnésio, 109,5 mg para 66 mg, insumo a adquirir).","**Comprar bisglicinato ferroso e bisglicinato de cobre com laudo** — nenhum laudo vigente dessas formas existe na máquina; a massa do ferro (39,98 mg) usa o último teor conhecido de um laudo vencido.","**Memorial de cálculo e ficha técnica inexistentes** — este produto é vendido sem nenhum documento de fabricação (achado do inventário de 16/09). O RT precisa emitir o memorial a partir desta proposta antes de qualquer produção.","**Cápsula:** confirmar tamanho e capacidade (assumida a cápsula 0 de 500 mg dos outros produtos).","**VDR de niacina para gestantes e lactantes** não foi extraído do Anexo VIII (pendência do gabarito) — a célula de %VD da niacina fica PENDENTE, não vazia por falta de VDR.","**Rótulo (a criar):** designação ''Suplemento alimentar em cápsulas'', público ''gestantes e lactantes'', tabela com as duas colunas de %VD, sem a frase genérica de gestantes."],"alternativas": ["**Óxido de magnésio** no lugar do bisglicinato (109,5 mg para 66 mg; a adquirir) — reduz a dependência do laudo vencido e libera 109 mg.","**Cálcio a 300 mg com 3 cápsulas por porção** (791 mg de carbonato) — só com mudança de porção, decisão do dono."],"mudancas": ["Grupo populacional: o cadastro dizia ''Adultos com 19 anos ou mais''; passa a ''Gestantes e lactantes'', com limites e %VD das colunas próprias (nome do produto, RDC 243/2018, art. 14, I, a).","Cálcio: 300 → 215 mg (carbonato 791 → 567,0 mg) — motivo: a porção não comporta 791 mg de carbonato; 215 mg = 110% do mínimo (195 mg nos dois grupos).","Magnésio: 60 → 66 mg (218,40 mg de bisglicinato a 30,22%) — motivo: 60 mg cravava o mínimo de gestantes; laudo novo obrigatório.","Ácido fólico: 800 → 500 µg (1.333,3 → 833,3 µg DFE) — motivo: acima dos dois tetos (1.138,3 / 1.162,3 µg DFE) e mínimo de gestantes de 666,6 µg DFE.","Vitamina B12: 10,46 → 8 µg — motivo: acima do teto de lactantes (10,07) e no teto de gestantes.","Vitamina D3: 50 → 40 µg — teto exato.","Ácido pantotênico: 5 → 4,5 mg — 91% do teto de lactantes (5,49).","Vitamina E: 3,35 → 5,0 mg de α-tocoferol (14,72 mg de pó) — margem de 0,5 mg sobre o mínimo de lactantes era insuficiente.","Dióxido de silício: 592,14 mg (sem fonte) → q.s.p.","Vitamina C, ferro, niacina, cobre: mantidos (ferro e cobre condicionados a laudo)."],"removidos": []}'::jsonb)
where f.slug = 'multi-vitta-gestante-e-lactante-em-capsula' and f.deleted_at is null;

