    metadata            = coalesce(f.metadata, '{}'::jsonb) - 'tabela_nutricional_2026_09_16' - 'tabela_nutricional_20260916' - 'reformulacao' || jsonb_build_object('reformulacao_2026_09_16', '{"data": "2026-09-16","fonte": "fase 3 - consolidacao de docs/conformidade/reformulacao/melatonina-triptofanos-encapsulados.md","veredito": "CONFORME CONDICIONADO A (laudo vigente de melatonina; laudo novo de bisglicinato de magnésio; laudo de ácido L-aspártico ou sua retirada; laudo de L-triptofano do lote a usar; emissão do memorial de cálculo pelo RT)","grupo_populacional": "adultos, coluna \"> 19 anos\" dos Anexos III e IV (a melatonina é ''NA'' em todos os outros grupos)","porcao_mg": 1000.0,"porcao_descricao": "1 g (2 cápsulas)","formato": "cápsula (sem memorial: tamanho e capacidade não registrados; assumida a cápsula 0 de 500 mg da linha)","soma_porcao_mg": 999.9997,"cabe": true,"linhas_composicao": 8,"tabela_nutricional": {"porcoes_por_embalagem": "30","porcao": "1 g (2 cápsulas)","grupos_vd": ["adultos_19_anos_ou_mais"],"linhas": [{"item": "Valor energético","quantidade": 2.8,"unidade": "kcal","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false,"kj": 12.0,"kcal_exato": 2.78},{"item": "Carboidratos","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares totais","quantidade": 0.0,"unidade": "g","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Açúcares adicionados","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 2,"nota": null,"pendente": false,"provisorio": false},{"item": "Proteínas","quantidade": 0.7,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 1},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Triptofano","quantidade": 500.0,"unidade": "mg","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Glutamina","quantidade": 95.0,"unidade": "mg","vd_pct": null,"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Aspartato","quantidade": 100.0,"unidade": "mg","vd_pct": null,"nivel": 1,"nota": "dose ajustada — PENDENTE laudo: 150 mg (2,8% do teto) → 100 mg (1,9%): libera 50 mg. O cadastro é a única fonte da dose; sem laudo, sem lote. Comprar/obter laudo ou retirar (não há mínimo).","pendente": false,"provisorio": true},{"item": "Gorduras totais","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras saturadas","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Gorduras trans","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 1,"nota": null,"pendente": false,"provisorio": false},{"item": "Fibras alimentares","quantidade": 0.0,"unidade": "g","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Sódio","quantidade": 0.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 0},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Biotina","quantidade": 40.0,"unidade": "µg","vd_pct": {"adultos_19_anos_ou_mais": 133},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Magnésio","quantidade": 70.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 17},"nivel": 0,"nota": "teor de laudo VENCIDO (lote 90844 (Analitic, fabricante 66342023062230), validade 21/06/2025) — pedir laudo novo e recalcular a massa pelo teor","pendente": false,"provisorio": true},{"item": "Zinco","quantidade": 10.0,"unidade": "mg","vd_pct": {"adultos_19_anos_ou_mais": 91},"nivel": 0,"nota": null,"pendente": false,"provisorio": false},{"item": "Melatonina","quantidade": 0.18,"unidade": "mg","vd_pct": null,"nivel": 0,"nota": "teor de laudo VENCIDO (lote 950151 (Analitic, fabricante MCS211210) — os 5 laudos de melatonina da máquina estão vencidos, validade 09/12/2024) — pedir laudo novo e recalcular a massa pelo teor","pendente": false,"provisorio": true}],"rodape": "*Percentual de valores diários fornecidos pela porção","regras": "Arredondamento: Anexo III da IN 75/2020 (paráfrase do gabarito de 16/09/2026). %VD: Anexo VIII da IN 75/2020 para o grupo do rótulo (macronutrientes: Anexo II), calculado sobre a quantidade declarada. Quantidade não significativa (Anexo IV): %VD 0. Sem VDR: célula em branco (RDC 429/2020, art. 12, §1º). Energia: fatores do Anexo XXII da IN 75 (kcal/g); kJ = kcal × 4,184.","provisoria": true},"advertencias_anexo_vi": [["Melatonina","Este produto não deve ser consumido por gestantes, lactantes, crianças e pessoas envolvidas em atividades que requerem atenção constante. Pessoas com enfermidades e/ou sob o uso de medicamentos, consulte seu médico."],["Aminoácidos","Este produto não deve ser consumido por gestantes, lactantes e crianças."]],"pendencias": ["**Laudo vigente de melatonina** do lote que a fábrica vai pesar — os cinco laudos da máquina venceram (o mais recente em 27/05/2026). Sem ele, o produto não pode ser fabricado: 0,18 mg é 85,7% do teto e qualquer teor acima do calculado aproxima do limite.","**Laudo novo de bisglicinato de magnésio** (90844 vencido) ou troca por óxido de magnésio (116,08 mg, a adquirir).","**L-triptofano:** laudo 950388 vence em 03/10/2026 — pedir laudo do lote que será usado.","**Ácido L-aspártico:** obter laudo (nenhum na máquina) ou retirar — decisão do dono; sem mínimo no Anexo III.","**Fosfatidilserina — decisão do dono:** retirada. Para voltar, precisa de insumo ''Fosfatidilserina de lecitina de soja'' com laudo de teor e origem, e de espaço na porção (ver alternativa).","**Memorial de cálculo inexistente:** o único documento é um dossiê gerado a partir do banco; o RT precisa emitir memorial com lotes antes de produzir. Confirmar cápsula (tamanho/capacidade).","**Rótulo (a criar):** designação, tabela nutricional da seção 5, lista de ingredientes, advertência específica da melatonina, ''preferencialmente à noite''.","**Folga de excipiente de 2,1%:** se o laudo novo do magnésio vier com teor abaixo de 30,22%, a massa de sal sobe e a fórmula deixa de fechar — recompor (reduzir triptofano ou trocar por óxido)."],"alternativas": ["**Óxido de magnésio** (116,08 mg para 70 mg de Mg; a adquirir) no lugar do bisglicinato: libera 115 mg, o que permitiria manter o triptofano em 572 mg ou reincluir 50 mg de fosfatidilserina de lecitina de soja quando houver laudo.","**Retirar o ácido L-aspártico** (sem laudo, sem mínimo): libera 100 mg e uma pendência.","**Fórmula simples da OP nº 586** (triptofano 800 mg + melatonina 0,21 mg), já produzida para outro cliente — é outro produto, não a fórmula do catálogo; fica só como referência de que a linha tem variantes."],"mudancas": ["Magnésio: 63 → 70 mg de Mg (231,63 mg de bisglicinato) — motivo: mínimo exato sem folga (Anexo III: 63 mg); e, na leitura como sal, abaixo do mínimo. Laudo novo obrigatório.","Zinco: 29,59 → 10 mg — motivo: teto exato; e 29,59 mg de Zn exigiriam 148,8 mg de sal.","Melatonina: 0,21 → 0,18 mg — motivo: teto exato (Anexo IV: 0,21 mg); laudo do lote em uso obrigatório (todos vencidos).","Biotina: 45 → 40 µg — teto exato.","L-triptofano: 572,38 → 500 mg — motivo: liberar massa para o magnésio; continua a 58% do teto.","Ácido L-aspártico: 150 → 100 mg — motivo: liberar massa; sem laudo (a adquirir ou retirar).","L-glutamina: 94,77 → 95 mg (arredondamento; laudo Lepuge válido).","Fosfatidilserina: retirada — origem e laudo inexistentes; massa real desconhecida.","Dióxido de silício: 20,01 → q.s.p. (20,9 mg)."],"removidos": [{"constituinte": "Fosfatidilserina","quantidade_mg": 70,"motivo": "origem (lecitina de soja) não declarada; sem laudo; massa real do insumo comercial desconhecida; não cabe com o magnésio no mínimo"}]}'::jsonb)
where f.slug = 'melatonina-triptofanos-encapsulados' and f.deleted_at is null;

