-- omega-pro-tg: NÃO RESOLVIDO
update public.formulas f set
    -- Omega: ingredients_list e nutritional_info NAO sao gravados (sem fonte); a tabela PROVISORIA fica em metadata
    ingredients_list    = f.ingredients_list,
