os": [],"_procedencia": {"memorial": "MEM-CALC-BIOGUMMY-rev02 (13/08/2026)","rotulo": "composicoes_rotulo.json/biogummy (BioGummy.pdf)","anexos": "IN 28/2018 consolidada, lida 16/09/2026","in75": "IN 75/2020 consolidada, lida 16/09/2026 08:40 UTC-4"}}'::jsonb)
