-- -------------------------------------------------------------------------------------
-- 6. AUTOCHECK - aborta a transacao inteira se o estado final nao bater
-- -------------------------------------------------------------------------------------
do $$
declare
    v_encontrado  integer;
    v_sem_fonte   integer;
    v_sem_insumo  integer;
    v_total       integer;
    v_omega       integer;
    r             record;
begin
    for r in
        select * from (values
            ('multivitaminico', 19),
            ('zma-zinco-magnesio-e-vitamina-d', 7),
            ('biotina-em-capsula', 21),
            ('dores-musculares', 13),
            ('focus-colina', 10),
            ('multi-vitta-gestante-e-lactante-em-capsula', 12),
            ('melatonina-triptofanos-encapsulados', 8),
            ('serena', 9),
            ('detox-matinal-lemon-shot-300g', 10),
            ('saude-intestinal', 8),
            ('moro-slim', 6),
            ('pro-energy', 9),
            ('emagrecedor-em-capsula', 6),
            ('slim-up-emagrecimento-em-gota', 12),
            ('shot-colageno-300-gramas', 9),
            ('bella-gummy-biotina-em-gummy', 5),
            ('creatina-monohidratada-150g-soluvel', 1),
            ('creatina-monohidratada-300g-soluvel', 1),
            ('creatina-gummy-sabor-frutas-vermelhas', 1),
            ('creatina-em-gummy-sabor-tutti-frutti', 1),
            ('melatonina-em-gummy-sabor-uva', 2),
            ('pre-treino-300-g', 13),
            ('pre-treino-creatina-sabor-limao-420g', 18)
        ) as e(slug, linhas)
    loop
        select count(*) into v_encontrado
        from public.formula_compositions fc
        join public.formulas f on f.id = fc.formula_id
        where f.slug = r.slug and f.deleted_at is null and fc.deleted_at is null and fc.active;
        if v_encontrado <> r.linhas then
            raise exception 'formula % deveria ter % linhas ativas de composicao depois da reformulacao, encontrado %', r.slug, r.linhas, v_encontrado;
        end if;
    end loop;

    select
        count(*) filter (where coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16'),
        count(*) filter (where fc.ingredient_id is null),
        count(*)
    into v_sem_fonte, v_sem_insumo, v_total
    from public.formula_compositions fc
    join public.formulas f on f.id = fc.formula_id
    where f.deleted_at is null and fc.deleted_at is null and fc.active
      and f.slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
          'detox-matinal-lemon-shot-300g',
          'saude-intestinal',
          'moro-slim',
          'pro-energy',
          'emagrecedor-em-capsula',
          'slim-up-emagrecimento-em-gota',
          'shot-colageno-300-gramas',
          'bella-gummy-biotina-em-gummy',
          'creatina-monohidratada-150g-soluvel',
          'creatina-monohidratada-300g-soluvel',
          'creatina-gummy-sabor-frutas-vermelhas',
          'creatina-em-gummy-sabor-tutti-frutti',
          'melatonina-em-gummy-sabor-uva',
          'pre-treino-300-g',
          'pre-treino-creatina-sabor-limao-420g'
      );
    if v_sem_fonte <> 0 then
        raise exception '% linha(s) ativa(s) das 23 formulas ainda sem metadata.fonte = reformulacao_2026-09-16 (linha antiga sobreviveu)', v_sem_fonte;
    end if;
    if v_sem_insumo <> 0 then
        raise exception '% linha(s) nova(s) sem ingredient_id (slug de insumo nao resolveu em public.ingredients)', v_sem_insumo;
    end if;
    if v_total <> 201 then
        raise exception 'esperado 201 linhas ativas de composicao nas 23 formulas reformuladas, encontrado %', v_total;
    end if;

    -- Omega Pro TG: composicao intocada (nenhuma linha desta fonte, nenhuma linha excluida por esta migration)
    select count(*) into v_omega
    from public.formula_compositions fc
    join public.formulas f on f.id = fc.formula_id
    where f.slug = 'omega-pro-tg' and f.deleted_at is null and (fc.metadata->>'fonte' = 'reformulacao_2026-09-16' or fc.reason_deleted = 'reformulação regulatória 2026-09-16');
    if v_omega <> 0 then
        raise exception 'omega-pro-tg nao deveria ter composicao tocada por esta migration, encontrado % linha(s)', v_omega;
    end if;

    select count(*) into v_encontrado from public.formulas f
    where f.deleted_at is null and f.slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
