-- -------------------------------------------------------------------------------------
-- 7. SELO DE CONFORMIDADE - zera nas 24 (a formula gravada e a PROPOSTA; o selo volta por migration propria,
--    com auditoria contra a formula efetivamente produzida, laudos e arte)
-- -------------------------------------------------------------------------------------
update public.formulas f set
    compliance_verified_at = null,
    compliance_norms       = null,
    compliance_source      = null
where f.deleted_at is null
  and f.slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
          'detox-matinal-lemon-shot-300g',
          'saude-intestinal',
          'moro-slim',
          'pro-energy',
          'emagrecedor-em-capsula',
          'slim-up-emagrecimento-em-gota',
          'shot-colageno-300-gramas',
          'omega-pro-tg',
          'bella-gummy-biotina-em-gummy',
          'creatina-monohidratada-150g-soluvel',
          'creatina-monohidratada-300g-soluvel',
          'creatina-gummy-sabor-frutas-vermelhas',
          'creatina-em-gummy-sabor-tutti-frutti',
          'melatonina-em-gummy-sabor-uva',
          'pre-treino-300-g',
          'pre-treino-creatina-sabor-limao-420g'
      )
  and (f.compliance_verified_at is not null or f.compliance_norms is not null or f.compliance_source is not null);

do $$
declare v_count integer;
begin
    select count(*) into v_count from public.formulas f
    where f.deleted_at is null and f.compliance_verified_at is not null and f.slug in (
          'multivitaminico',
          'zma-zinco-magnesio-e-vitamina-d',
          'biotina-em-capsula',
          'dores-musculares',
          'focus-colina',
          'multi-vitta-gestante-e-lactante-em-capsula',
          'melatonina-triptofanos-encapsulados',
          'serena',
          'detox-matinal-lemon-shot-300g',
          'saude-intestinal',
          'moro-slim',
          'pro-energy',
          'emagrecedor-em-capsula',
          'slim-up-emagrecimento-em-gota',
          'shot-colageno-300-gramas',
          'omega-pro-tg',
          'bella-gummy-biotina-em-gummy',
          'creatina-monohidratada-150g-soluvel',
          'creatina-monohidratada-300g-soluvel',
          'creatina-gummy-sabor-frutas-vermelhas',
          'creatina-em-gummy-sabor-tutti-frutti',
          'melatonina-em-gummy-sabor-uva',
          'pre-treino-300-g',
          'pre-treino-creatina-sabor-limao-420g'
      );
    if v_count <> 0 then
        raise exception 'esperado 0 formulas com compliance_verified_at preenchido apos a reformulacao, encontrado %', v_count;
    end if;
end $$;
